"""Export reviewable static reports with working SQL/result anchors from real receipts."""
import argparse
import hashlib
import html
import json
import re
from pathlib import Path
from uuid import UUID

import psycopg

from config import ROOT,db_kwargs
from scripts.common import start_log,record
from scripts.evidence import publish_log


def render(case,stored):
    response=case['response']
    text=html.escape(str(response['answer']))
    text=re.sub(r'\[证据\]\(#result-([0-9a-fA-F-]{36})\)',r'<a href="#result-\1">证据</a>',text)
    # Only allow the exact red annotation generated by the runtime scanner.
    text=text.replace('&lt;span style=&quot;color:red&quot; title=&quot;未验证数字&quot;&gt;','<span style="color:red" title="未验证数字">').replace('&lt;/span&gt;','</span>')
    blocks=['<!doctype html><html lang="zh"><meta charset="utf-8"><title>证据审阅报告</title>',
        '<style>body{font:16px/1.6 system-ui;max-width:1100px;margin:32px auto;padding:0 24px;color:#17212b}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f6f8;padding:16px}table{border-collapse:collapse;font-size:14px}td,th{border:1px solid #ccd3da;padding:7px}section{margin:32px 0}a{color:#145fbe}</style>',
        '<h1>真实运行报告及证据</h1>', '<p>问题 '+html.escape(case['question_id'])+'；任务 '+html.escape(case['task_id'])+'</p>',
        '<h2>原始问题</h2><p>'+html.escape(case.get('question',case['question_id']))+'</p><h2>回答</h2>',
        '<pre>'+text+'</pre><h2>结构化结论</h2>']
    for claim in response['claims']:
        links=' '.join('<a href="#result-'+html.escape(ref)+'">证据</a>' for ref in claim['evidence'])
        blocks+=['<p>'+html.escape(claim['text'])+' '+links+'</p><pre>'+html.escape(json.dumps(claim['value'],ensure_ascii=False,indent=2))+'</pre>']
    for ref,result in stored.items():
        blocks+=['<section id="result-'+ref+'"><h2>SQL 证据 '+ref+'</h2>',
            '<p>数据版本：'+html.escape(result['data_version'])+'</p><pre>'+html.escape(result['sql'])+'</pre>']
        columns=result['columns']
        blocks+=['<table><thead><tr>'+''.join('<th>'+html.escape(c)+'</th>' for c in columns)+'</tr></thead><tbody>']
        for row in result['rows']:
            blocks+=['<tr>'+''.join('<td>'+html.escape(str(row.get(c)))+'</td>' for c in columns)+'</tr>']
        blocks+=['</tbody></table></section>']
    blocks+=['<h2>独立核查与评分记录</h2><pre>'+html.escape(json.dumps({'evidence_check':case['evidence'],'model_grade':case.get('judge'),'human_verdict':None},ensure_ascii=False,indent=2))+'</pre></html>']
    return '\n'.join(blocks)


def export(receipts,limit=10):
    logger,path=start_log('report_exports')
    sources=[(Path(p),json.loads(Path(p).read_text(encoding='utf-8'))) for p in receipts]
    queues=[[(p,r,c) for c in r['cases'] if c['category']=='D' and 'response' in c] for p,r in sources]
    selected=[]
    while len(selected)<limit and any(queues):
        for queue in queues:
            if queue and len(selected)<limit:selected.append(queue.pop(0))
    review=['# 报告审查清单','','全部来源于真实 dev 运行。自动核查、模型评分和人工审阅分别记录；人工结论与人工评分留空，尚未声称校准。HTML 内证据链接可跳到本任务 SQL 和完整保存结果。','',
        '| 模式 | 题目 | 报告 | 无证据结论 | 无证据数字 | 模型评分 | 人工核查 | 人工评分 |','| --- | --- | --- | --- | --- | --- | --- | --- |']
    with psycopg.connect(**db_kwargs('agent','app')) as conn:
        for source,run,case in selected:
            question=conn.execute('SELECT question FROM tasks WHERE task_id=%s',(UUID(case['task_id']),)).fetchone()
            if not question:raise ValueError('Report task is missing')
            case={**case,'question':question[0]}
            refs=sorted({ref for c in case['response']['claims'] for ref in c['evidence']})
            rows=conn.execute('SELECT result_id,sql,columns,rows,data_version FROM query_results WHERE task_id=%s AND result_id=ANY(%s)',
                (UUID(case['task_id']),[UUID(r) for r in refs])).fetchall()
            stored={str(r[0]):dict(zip(('sql','columns','rows','data_version'),r[1:])) for r in rows}
            missing=sorted(set(refs)-set(stored))
            for ref in missing:
                stored[ref]={'sql':'未找到属于本任务的证据；不读取其他任务的数据。','columns':[],'rows':[],'data_version':'unavailable'}
            output=ROOT/'evidence'/('report_'+case['task_id']+'.html')
            content=render(case,stored)
            if output.exists() and output.read_text(encoding='utf-8')!=content:raise ValueError('Report export is immutable')
            if not output.exists():output.write_text(content,encoding='utf-8',newline='\n')
            record(logger,'report_exported',question_id=case['question_id'],task_id=case['task_id'],file=output.name,
                sha256=hashlib.sha256(output.read_bytes()).hexdigest(),source_receipt=source.name,source_log=run['source_log'])
            audit=case['evidence'];grade=case.get('judge') or {}
            review.append(f"| {run.get('agent_mode','single')} | {case['question_id']} | [{output.name}](../evidence/{output.name}) | {audit['unsupported_claims']} / {audit['claim_count']} | {audit['unsupported_numbers']} / {audit['report_number_count']} | {grade.get('score','')} |  |  |")
    receipt=publish_log(path)
    review+=['',f'导出收据：[{receipt.name}](../evidence/{receipt.name})；原始日志 `{path.name}`。']
    (ROOT/'eval/REPORT_REVIEW.md').write_text('\n'.join(review)+'\n',encoding='utf-8',newline='\n')
    print('Evidence:',receipt.name)


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('receipts',nargs='+');parser.add_argument('--limit',type=int,default=10)
    args=parser.parse_args();export(args.receipts,args.limit)
